/**
 * The Merchandizable demo shop in the prototype. Chart and fit outcomes come from merchandizable.json,
 * generated by services/api/scripts/export_catalog.py. This file only looks them up: no fit rules here.
 */
import { hostOf } from "@/lib/format";
import type { DemoCheck, DemoChart, DemoFit, Profile } from "../types";
import fixture from "./merchandizable.json";

export type DemoProduct = (typeof fixture.products)[number];
type StoredFit = Omit<DemoFit, "mode">;

export const DEMO_SHOP = fixture.shop;
export const DEMO_CHART = fixture.chart as DemoChart;
export const DEMO_PRODUCTS: DemoProduct[] = fixture.products;

const PERSONAL_NOTE =
  "This browser prototype can't run the Personal Fit comparison, which happens in the Python engine.";

function pageKey(url: string): string {
  const path = new URL(url.includes("://") ? url : `https://${url}`).pathname;
  return `${hostOf(url)}${path.replace(/\/$/, "")}`;
}

export function demoProductForUrl(url: string): DemoProduct | undefined {
  try {
    const key = pageKey(url);
    return DEMO_PRODUCTS.find((p) => pageKey(p.input_url) === key);
  } catch {
    return undefined;
  }
}

function fitFor(product: DemoProduct, profile: Profile): DemoFit {
  if (profile.fit_mode === "personal_fit") {
    const stored: StoredFit = product.personal_fit;
    return {
      ...stored,
      mode: "personal_fit",
      reasons: [...stored.reasons, PERSONAL_NOTE],
    };
  }
  const outcomes: Record<string, StoredFit> = product.quick_fit;
  const sizes: Record<string, string | undefined> = profile.quick_sizes;
  const size = product.category ? sizes[product.category] : undefined;
  return { ...outcomes[size ?? "none"], mode: "quick_fit" };
}

export function buildDemoCheck(
  product: DemoProduct,
  profile: Profile,
): DemoCheck {
  return {
    shop_id: DEMO_SHOP.id,
    shop_name: DEMO_SHOP.name,
    product_type: product.product_type,
    sold_sizes: product.sold_sizes,
    price_cents: product.price_cents,
    currency: product.currency,
    offer: {
      listingId: product.id,
      retailerId: DEMO_SHOP.id,
      retailerName: DEMO_SHOP.name,
      url: product.product_url,
    },
    fit: fitFor(product, profile),
    chart: DEMO_CHART,
  };
}
